import {icon,esc} from './lib/icons.js';
import {lineChart,bars,sparkline,gauge} from './lib/charts.js';
import {mountMap} from './lib/map.js';
import {REGIONS,LAYERS,getRegion} from './data/fixtures.js';
import {provider,providerMode} from './services/provider.js';

const app=document.querySelector('#app');
const state={
 page:'overview',regionId:'huanuco',period:'7d',layers:['fire','rain'],dashboard:null,series:null,hotspots:[],alerts:[],integrations:[],models:[],regions:REGIONS,
 modal:null,search:'',crop:'cafe',deltaRain:0,deltaTemp:0,earthSplit:52,modelResult:null,modelBusy:false,assistantBusy:false,
 chat:[{role:'assistant',text:'Bienvenido a **TERRA Intelligence**. Soy el asistente de demostración. Puedes preguntarme por incendios, lluvias, cultivos o cambios territoriales. Todos los valores que verás son simulados.'}],
 filterSeverity:'all',alertFilter:'all',hotspotFilter:'all',sidebarMobile:false,loading:true,error:null,lastUpdate:Date.now(),toast:null
};
let destroyMap=()=>{},toastTimer=null;
const PAGES={overview:['Visión general','Una visión integrada del comportamiento ambiental','layout'],map:['Explorador geoespacial','Monitoreo territorial interactivo','map'],climate:['Inteligencia climática','Anomalías, tendencias y series temporales','cloud-sun'],fire:['Monitor de incendios','Focos térmicos, distribución y condiciones','flame'],agro:['Inteligencia agrícola','Indicadores para decisiones agroclimáticas','sprout'],earth:['Cambios territoriales','Exploración de superficies y radar SAR','satellite'],models:['Centro de inteligencia artificial','Modelos especializados y asistente contextual','brain'],alerts:['Centro de alertas','Eventos demostrativos y seguimiento territorial','bell'],reports:['Informes y exportación','Documentación de análisis y series simuladas','file'],integrations:['Fuentes e integraciones','Conectores preparados para datos reales','database'],settings:['Configuración','Estado del entorno y puntos de conexión','settings']};
const NAV=[['ESPACIO DE TRABAJO',[['overview','Resumen ejecutivo'],['map','Mapa global']] ],['INTELIGENCIA TERRITORIAL',[['climate','Clima y anomalías'],['fire','Incendios'],['agro','Agricultura'],['earth','Cambios SAR']] ],['HERRAMIENTAS',[['models','TERRA AI'],['alerts','Alertas'],['reports','Informes']] ],['PLATAFORMA',[['integrations','Integraciones'],['settings','Configuración']]]];
const number=(v,d=0)=>Number(v).toLocaleString('es-PE',{maximumFractionDigits:d,minimumFractionDigits:d});
function badge(text,kind='neutral'){return `<span class="badge badge-${kind}">${esc(text)}</span>`;}
function toast(text){state.toast=text;render();clearTimeout(toastTimer);toastTimer=setTimeout(()=>{state.toast=null;render();},3500);}
function aside(){return `<aside class="sidebar ${state.sidebarMobile?'sidebar-open':''}">
 <div class="sidebar-brand"><div class="brand-orb">${icon('globe',25)}</div><div class="brand-type"><strong>TERRA<span>AI</span></strong><small>EARTH INTELLIGENCE</small></div><span class="brand-dot"></span></div>
 <div class="workspace-chip"><span class="workspace-icon">${icon('globe',17)}</span><div><strong>Earth Observatory</strong><small>Demo Workspace</small></div>${icon('down',15,'subtle')}</div>
 <nav>${NAV.map(([head,items])=>`<div class="nav-group"><div class="nav-heading">${head}</div>${items.map(([id,label])=>`<button type="button" class="nav-item ${state.page===id?'active':''}" data-nav="${id}">${icon(PAGES[id][2],19)}<span>${label}</span>${id==='alerts'?`<span class="nav-count">${state.alerts.filter(a=>a.level==='critical').length||2}</span>`:''}${id==='models'?'<span class="nav-new">AI</span>':''}</button>`).join('')}</div>`).join('')}</nav>
 <div class="sidebar-bottom"><div class="satellite-card"><div class="satellite-card-top">${icon('satellite',18)} <span>ESTADO DEL ENTORNO</span></div><strong>Simulador conectado</strong><p>4 módulos científicos activos<br/>0 fuentes de datos reales</p><div class="small-track"><span style="width:72%"></span></div></div><div class="side-footer">${icon('shield',14)} DEMO / SANTRIX STUDIO <span>v1.0</span></div></div>
 </aside>`;}
function topbar(){const [title,subtitle,ico]=PAGES[state.page],region=getRegion(state.regionId);return `<header class="topbar">
  <div class="topbar-left"><button type="button" class="icon-button mobile-menu" data-action="sidebar">${icon('menu',21)}</button><div class="breadcrumbs">Plataforma ${icon('chevron',13)} <span>${esc(title)}</span></div></div>
  <div class="topbar-right"><button class="search-box" data-action="search" type="button">${icon('search',17)} <span>Buscar región, módulo o función...</span><kbd>Ctrl K</kbd></button><div class="top-sep"></div><div class="live-chip"><span class="pulse-dot"></span> Simulación activa</div><button class="icon-button" title="Actualizar vista" data-action="refresh">${icon('refresh',18)}</button><button class="icon-button bell-button" title="Ver alertas" data-nav="alerts">${icon('bell',19)}<i></i></button><div class="avatar" title="SANTRIX · Proyecto NASA">S</div></div>
 </header>`;}
function demoStrip(){return `<div class="demo-strip">${icon('info',16)} <span><strong>ENTORNO DE DEMOSTRACIÓN:</strong> información, alertas e inferencias 100 % simuladas. No representa observaciones de NASA ni pronósticos reales.</span><button data-nav="integrations">Ver conectores ${icon('arrow',14)}</button></div>`;}
function pageHead({showRegion=true,action=true}={}){const [title,subtitle,ico]=PAGES[state.page];return `<div class="page-heading"><div><div class="page-kicker"><span class="kicker-line"></span> EARTH INTELLIGENCE PLATFORM / 2026</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="page-controls">${showRegion?`<label class="select-wrap">${icon('pin',16)}<select id="region-select" aria-label="Seleccionar región">${state.regions.map(r=>`<option value="${r.id}" ${state.regionId===r.id?'selected':''}>${esc(r.name)}, ${esc(r.country)}</option>`).join('')}</select>${icon('down',14)}</label>`:''}${action?`<button class="btn btn-primary" data-action="export-html">${icon('download',16)} Exportar informe</button>`:''}</div></div>`;}
function periodSelect(){return `<div class="segmented period-segment">${[['24h','24 H'],['7d','7 días'],['30d','30 días'],['1y','1 año']].map(([key,label])=>`<button data-period="${key}" class="${state.period===key?'selected':''}">${label}</button>`).join('')}</div>`;}
function pillLegend(){return LAYERS.filter(l=>state.layers.includes(l.id)).map(l=>`<span class="legend-item"><i style="background:${l.color}"></i>${l.name}</span>`).join('')||'<span class="muted">Sin capas seleccionadas</span>';}
function mapPanel({large=false,heading='Observatorio terrestre',toolbar=true}={}){return `<section class="card map-panel ${large?'map-panel-wide':''}">
 <div class="card-header map-header"><div><div class="overline">${icon('globe',15)} VISUALIZACIÓN GEOESPACIAL</div><h2>${heading}</h2></div><div class="header-actions"><span class="tag-outline">${icon('activity',13)} Mapa interactivo</span><button class="icon-button ghost-icon" data-nav="map" title="Expandir mapa">${icon('maximize',17)}</button></div></div>
 ${toolbar?`<div class="map-toolbar"><div class="layer-toggles">${LAYERS.map(l=>`<button data-layer="${l.id}" class="layer-pill ${state.layers.includes(l.id)?'on':''}"><span style="--layer-color:${l.color}"></span>${l.name}</button>`).join('')}</div><div class="toolbar-trailing">${icon('layers',15)} ${state.layers.length} capas</div></div>`:''}
 <div class="geo-viewport ${large?'geo-large':''}" id="geo-viewer"><canvas class="geo-canvas" aria-label="Mapa interactivo de geografía real y puntos demostrativos"></canvas><div class="geo-top-left"><span class="geo-badge"><span class="pulse-dot"></span> DEMO LIVE</span><span class="geo-date">${new Date().toLocaleDateString('es-PE',{day:'2-digit',month:'short',year:'numeric'})}</span></div><div class="geo-zoom"><button data-map-zoom-in title="Acercar">${icon('plus',17)}</button><button data-map-zoom-out title="Alejar">${icon('minus',17)}</button><button data-map-reset title="Restablecer mapa">${icon('target',17)}</button></div><div class="geo-coordinate">REGIÓN ACTIVA <b>${esc(getRegion(state.regionId).name)}</b></div><div class="map-scale"><i></i> 250 km*</div></div>
 <div class="map-footer"><div class="legend">${pillLegend()}</div><span class="map-note">${icon('info',13)} Representación ilustrativa · datos ficticios · escala visual no cartográfica*</span></div>
 </section>`;}
function metricCards(){const d=state.dashboard.metrics,s=state.series;const items=[
 {label:'Temperatura estimada',v:`${number(d.temp,1)}°`,unit:'C',delta:`+${number(d.anomaly,1)}° vs referencia`,col:'#f3bf78',ico:'thermometer',spark:s.temp},
 {label:'Focos térmicos',v:number(d.hotspots),unit:'eventos',delta:`+${d.trend}% cambio ilustrativo`,col:'#fa9674',ico:'flame',spark:s.fire},
 {label:'Precipitación acumulada',v:number(d.precip),unit:'mm',delta:'Periodo sintético actual',col:'#79aaf9',ico:'cloud',spark:s.rain},
 {label:'Humedad del suelo',v:`${d.soil}%`,unit:'índice',delta:'Estimación de demostración',col:'#72d8ae',ico:'sprout',spark:s.vegetation}
 ];return `<div class="metric-grid">${items.map(x=>`<div class="card metric-card"><div class="metric-top"><span>${esc(x.label)}</span><div class="metric-icon" style="color:${x.col};background:${x.col}16">${icon(x.ico,20)}</div></div><div class="metric-val">${x.v}<small>${x.unit}</small></div><div class="metric-bottom"><span>${icon('trend',14)} ${esc(x.delta)}</span>${sparkline(x.spark.slice(-9),x.col)}</div></div>`).join('')}</div>`;}
function riskLabel(value){return value>=80?['Muy elevado','danger']:value>=65?['Elevado','warning']:value>=45?['Moderado','neutral']:['Bajo','good'];}
function insightPanel(){const r=getRegion(state.regionId),m=state.dashboard.metrics,rl=riskLabel(m.fireRisk);return `<section class="card insight-panel"><div class="card-header"><div><div class="overline">${icon('brain',15)} ANÁLISIS TERRITORIAL</div><h2>TERRA Insights</h2></div>${badge('SIMULADO','purple')}</div><div class="insight-body"><div class="risk-block">${gauge(m.fireRisk,m.fireRisk>80?'#f59b72':'#71dbaf',114)}<div class="risk-info"><span>Índice conceptual de condiciones</span><strong>${rl[0]}</strong>${badge(`Índice ${m.fireRisk}/100`,rl[1])}</div></div><div class="soft-divider"></div><div class="insight-kicker">${icon('zap',16)} INTERPRETACIÓN DE ESCENARIO</div><p class="insight-text">${esc(state.dashboard.narrative)}</p><div class="insight-factors"><span>${icon('thermometer',15)} ${number(m.anomaly,1)}° anomalía</span><span>${icon('flame',15)} ${m.hotspots} registros</span><span>${icon('leaf',15)} ${m.soil}% suelo</span></div><button class="btn btn-secondary full-width" data-nav="models">Abrir centro de inteligencia ${icon('arrow',16)}</button></div></section>`;}
function shortAlerts(){return `<section class="card short-alerts"><div class="card-header"><div><div class="overline">${icon('bell',15)} NOTIFICACIONES</div><h2>Actividad destacada</h2></div><button class="text-link" data-nav="alerts">Ver todas ${icon('arrow',14)}</button></div>${state.alerts.slice(0,3).map(a=>`<button class="alert-short" data-alert="${a.id}"><span class="level-dot ${a.level}"></span><span><strong>${esc(a.title)}</strong><small>${esc(a.area)} · hace ${a.hours} h</small></span>${icon('chevron',16)}</button>`).join('')}</section>`;}
function overview(){const s=state.series;return `${pageHead()}<div class="scope-row"><div>${badge('● 4 motores científicos','good')} <span class="scope-desc">Vista conjunta de indicadores ambientales · ${esc(getRegion(state.regionId).name)}, ${esc(getRegion(state.regionId).country)}</span></div>${periodSelect()}</div>${metricCards()}<div class="dashboard-grid"><div class="stack">${mapPanel()}<div class="two-charts"><section class="card chart-card"><div class="card-header"><div><div class="overline">CLIMATE MONITOR</div><h2>Temperatura y precipitación</h2></div>${badge('Serie sintética')}</div>${lineChart({labels:s.labels,series:[{values:s.temp,color:'#f4bb73'},{values:s.rain,color:'#6baff4'}],height:219})}<div class="chart-legends"><span><i style="background:#f4bb73"></i> Temperatura (°C)</span><span><i style="background:#6baff4"></i> Precipitación (mm)</span></div></section><section class="card chart-card"><div class="card-header"><div><div class="overline">FIRE OBSERVATION</div><h2>Actividad térmica</h2></div>${badge('MODIS + VIIRS · Demo')}</div>${bars({labels:s.labels,values:s.fire,height:219,color:'#ef9e79'})}<div class="chart-legends"><span><i style="background:#ef9e79"></i> Registros ilustrativos por intervalo</span></div></section></div></div><div class="stack">${insightPanel()}${shortAlerts()}<section class="card data-sources-card"><div class="small-card-title">${icon('database',17)} Fuente de información</div><div class="source-row"><span class="source-logo">N</span><div><strong>NASA Earthdata</strong><small>Conector disponible, sin vincular</small></div>${badge('PENDIENTE')}</div><div class="source-row"><span class="source-logo">T</span><div><strong>TERRA Simulation Engine</strong><small>Datos sintéticos locales</small></div>${badge('ACTIVO','good')}</div><button class="text-link" data-nav="integrations">Administrar integraciones ${icon('arrow',14)}</button></section></div></div>`;}
function mapView(){return `${pageHead()}<div class="scope-row"><div class="subtle-line">${icon('compass',16)} Arrastra para explorar, usa la rueda para acercar y selecciona los puntos regionales.</div>${periodSelect()}</div>${mapPanel({large:true,heading:'Mapa de observación planetaria'})}<div class="three-columns">${[
  ['fire','Actividad térmica',state.dashboard.metrics.hotspots,'eventos simulados'],['climate','Anomalía térmica',`+${number(state.dashboard.metrics.anomaly,1)} °C`,'respecto a referencia'],['earth','Cambio territorial',`${number(state.dashboard.metrics.change,1)} km²`,'escenario conceptual']
 ].map(([p,t,v,s])=>`<button class="card map-stats" data-nav="${p}"><span class="muted">${t}</span><strong>${v}</strong><small>${s}</small>${icon('arrow',18)}</button>`).join('')}</div>`;}
function sectionIntro(text){return `<div class="section-notice">${icon('info',16)} ${text}</div>`;}
function climateView(){const s=state.series,r=getRegion(state.regionId),m=state.dashboard.metrics;return `${pageHead()}<div class="scope-row"><div class="subtle-line">${icon('clock',16)} Series temporales exploratorias | Datos no observacionales</div>${periodSelect()}</div><div class="three-columns feature-metrics">${[
 ['Temperatura media',`${number(m.temp,1)} °C`,'Promedio del escenario','#f5bd7d'],['Anomalía de temperatura',`+${number(m.anomaly,1)} °C`,'Diferencia sintética','#f5cc75'],['Precipitación',`${number(m.precip)} mm`,'Acumulado conceptual','#76b0f9']
 ].map(a=>`<div class="card feature-metric"><span>${a[0]}</span><strong style="color:${a[3]}">${a[1]}</strong><small>${a[2]}</small></div>`).join('')}</div><div class="two-columns"><section class="card chart-card big-chart"><div class="card-header"><div><div class="overline">CLIMATENET / TEMPERATURA</div><h2>Evolución térmica</h2></div>${badge('Modelo conceptual','purple')}</div>${lineChart({labels:s.labels,series:[{values:s.temp,color:'#f6c17e'}],height:265,unit:' °C'})}<div class="chart-legends"><span><i style="background:#f6c17e"></i> Valores sintéticos</span></div></section><section class="card chart-card big-chart"><div class="card-header"><div><div class="overline">NASA GPM / CONECTOR PENDIENTE</div><h2>Precipitación acumulada</h2></div>${badge('Modelo conceptual','purple')}</div>${bars({labels:s.labels,values:s.rain,color:'#7eb7ff',height:265,unit:' mm'})}<div class="chart-legends"><span><i style="background:#7eb7ff"></i> Series ficticias de precipitación</span></div></section></div><div class="two-columns bottom-gap"><section class="card info-card"><div class="overline">EXPLICACIÓN CIENTÍFICA</div><h2>Cómo se interpretan anomalías</h2><p>Una anomalía compara una medición con un valor de referencia del mismo periodo. Cuando conectemos NASA POWER y GPM, el motor podrá calcular series históricas, tendencias y su incertidumbre.</p><div class="info-list"><div>${icon('check',16)} Control estacional y referencia climatológica</div><div>${icon('check',16)} Comparaciones por territorio y periodo</div><div>${icon('check',16)} Indicadores con fuente y fecha de observación</div></div></section><section class="card info-card"><div class="overline">INTERPRETACIÓN DE LA REGIÓN</div><h2>${esc(r.name)} · Escenario sintético</h2><p>Temperatura ilustrativa de ${number(m.temp,1)} °C y una anomalía de +${number(m.anomaly,1)} °C. Estos valores solo permiten probar la interfaz, no analizar el clima verdadero.</p><button data-nav="models" class="btn btn-secondary">${icon('brain',16)} Explorar ClimateNet</button></section></div>`;}
function fireView(){const d=state.dashboard.metrics,filtered=state.hotspots.filter(h=>state.hotspotFilter==='all'||h.level===state.hotspotFilter).slice(0,14);return `${pageHead()}<div class="scope-row"><div class="subtle-line">${icon('flame',16)} MODIS + VIIRS · el módulo de armonización se conectará al backend científico</div>${periodSelect()}</div><div class="three-columns feature-metrics">${[['Focos térmicos',number(d.hotspots),'Periodo simulado'],['Condiciones asociadas',`${d.fireRisk}/100`,'Índice ilustrativo'],['Anomalía térmica',`+${number(d.anomaly,1)} °C`,'Variable auxiliar']].map(x=>`<div class="card feature-metric"><span>${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')}</div><div class="fire-layout">${mapPanel({large:false,heading:'Exploración de focos térmicos'})}<section class="card hotspot-panel"><div class="card-header"><div><div class="overline">REGISTROS ARTIFICIALES</div><h2>Detecciones térmicas</h2></div><span class="muted text-small">${filtered.length} filas</span></div><div class="filter-bar"><button data-hotspot="all" class="filter-chip ${state.hotspotFilter==='all'?'active':''}">Todos</button><button data-hotspot="Alto" class="filter-chip ${state.hotspotFilter==='Alto'?'active':''}">Intensidad alta</button><button data-hotspot="Moderado" class="filter-chip ${state.hotspotFilter==='Moderado'?'active':''}">Moderada</button></div><div class="table-wrap"><table><thead><tr><th>Referencia</th><th>Fuente</th><th>FRP (MW)*</th><th>Nivel</th></tr></thead><tbody>${filtered.map(h=>`<tr class="data-row" data-hotspot-row="${h.id}"><td><strong>${h.id}</strong><small>${number(h.lat,2)}, ${number(h.lon,2)}</small></td><td>${h.source}</td><td>${h.frp}</td><td>${badge(h.level,h.level==='Alto'?'danger':h.level==='Moderado'?'warning':'good')}</td></tr>`).join('')}</tbody></table></div><div class="table-foot">* Potencia radiativa ficticia · no corresponde a detecciones reales.</div></section></div><div class="bottom-gap">${sectionIntro('Los registros reales MODIS y VIIRS tienen resoluciones diferentes. El backend implementará criterios de armonización antes de compararlos.')}</div>`;}
const CROPS={cafe:{label:'Café',minT:18,maxT:26,rain:105},cacao:{label:'Cacao',minT:22,maxT:30,rain:160},maiz:{label:'Maíz',minT:18,maxT:30,rain:85},papa:{label:'Papa',minT:10,maxT:20,rain:85},arroz:{label:'Arroz',minT:21,maxT:34,rain:155}};
function agroScore(){const m=state.dashboard.metrics,c=CROPS[state.crop];const t=m.temp+state.deltaTemp,p=m.precip*(1+state.deltaRain/100);const tempScore=Math.max(0,100-Math.max(c.minT-t,t-c.maxT,0)*16);const rainScore=Math.max(0,100-Math.abs(p-c.rain)/Math.max(c.rain,1)*80);const soilScore=m.soil;return Math.max(5,Math.min(99,Math.round(tempScore*.40+rainScore*.38+soilScore*.22)));}
function agroView(){const m=state.dashboard.metrics,score=agroScore(),c=CROPS[state.crop];return `${pageHead()}<div class="scope-row"><div class="subtle-line">${icon('sprout',16)} Simulador de escenarios agronómicos, sin recomendaciones operativas reales</div>${periodSelect()}</div><div class="agro-grid"><section class="card scenario-panel"><div class="card-header"><div><div class="overline">AGROCLIMATE AI</div><h2>Laboratorio de escenarios</h2></div>${badge('Interactivo','good')}</div><p class="card-description">Modifica variables ambientales para observar cómo reaccionaría un indicador ilustrativo. No representa la aptitud real de una parcela.</p><label class="form-label" for="crop">Cultivo de referencia</label><div class="full-select"><select id="crop">${Object.entries(CROPS).map(([k,v])=>`<option value="${k}" ${k===state.crop?'selected':''}>${v.label}</option>`).join('')}</select>${icon('down',16)}</div><div class="range-head"><span>Ajuste de precipitación</span><strong>${state.deltaRain>0?'+':''}${state.deltaRain}%</strong></div><input type="range" id="delta-rain" min="-60" max="60" value="${state.deltaRain}" step="5"/><div class="range-extents"><span>-60%</span><span>+60%</span></div><div class="range-head"><span>Ajuste de temperatura</span><strong>${state.deltaTemp>0?'+':''}${state.deltaTemp.toFixed(1)} °C</strong></div><input type="range" id="delta-temp" min="-6" max="6" value="${state.deltaTemp}" step="0.5"/><div class="range-extents"><span>-6 °C</span><span>+6 °C</span></div><button class="btn btn-secondary full-width" data-action="reset-agro">${icon('refresh',16)} Restablecer escenario</button></section><section class="card agro-result"><div class="card-header"><div><div class="overline">INTERPRETACIÓN DIDÁCTICA</div><h2>Respuesta del escenario</h2></div>${badge('NO VALIDADO','warning')}</div><div class="agro-gauge">${gauge(score,score>=75?'#71dcaa':score>=50?'#eec275':'#f29c7c',154)}<div><div class="muted">Compatibilidad ilustrativa</div><h3>${score>=75?'Favorable':score>=50?'Condiciones variables':'Requiere atención'}</h3><p>Indicador sintético para ${c.label.toLowerCase()} en ${getRegion(state.regionId).name}. No sustituye análisis del suelo ni asesoría agronómica.</p></div></div><div class="agro-variable-grid"><div><span>Temperatura</span><strong>${number(m.temp+state.deltaTemp,1)} °C</strong></div><div><span>Precipitación</span><strong>${number(m.precip*(1+state.deltaRain/100))} mm</strong></div><div><span>Suelo (demo)</span><strong>${m.soil}%</strong></div><div><span>Cultivo</span><strong>${c.label}</strong></div></div><div class="suggestion-box">${icon('info',18)} Los valores de referencia son arbitrarios para probar interacciones. Conectar perfiles agronómicos locales antes de habilitar recomendaciones.</div></section></div><div class="two-columns bottom-gap"><section class="card chart-card"><div class="card-header"><div><div class="overline">SERIE TEMPORAL</div><h2>Índice de vegetación ilustrativo</h2></div></div>${lineChart({labels:state.series.labels,series:[{values:state.series.vegetation,color:'#76dcb1'}],height:206,area:true})}</section><section class="card info-card"><div class="overline">FUTURO CONECTOR AGRÍCOLA</div><h2>Qué falta para recomendaciones reales</h2><div class="info-list"><div>${icon('check',16)} Información de parcelas y variedades</div><div>${icon('check',16)} Textura y profundidad del suelo</div><div>${icon('check',16)} Calendarios de siembra y riego</div><div>${icon('check',16)} Validación con especialistas y campo</div></div><button class="btn btn-secondary" data-nav="integrations">${icon('plug',16)} Ver conexiones pendientes</button></section></div>`;}
function earthView(){const m=state.dashboard.metrics;return `${pageHead()}${sectionIntro('Comparador visual generado por CSS; no muestra imágenes SAR auténticas. El enchufe /connectors/nasa/nisar queda preparado para escenas reales.')}<div class="earth-layout"><section class="card earth-card"><div class="card-header"><div><div class="overline">EARTHVISION AI / SAR</div><h2>Explorador de cambios superficiales</h2></div>${badge('VISTA SINTÉTICA','purple')}</div><div class="comparison" id="comparison"><div class="terrain before"></div><div class="terrain after" id="earth-after" style="clip-path:inset(0 ${100-state.earthSplit}% 0 0)"></div><div class="comparison-divider" id="split-divider" style="left:${state.earthSplit}%"><span>${icon('chevron',15)}${icon('chevron',15)}</span></div><span class="comparison-tag left">ANTES · T0</span><span class="comparison-tag right">DESPUÉS · T1</span><div class="terrain-grid"></div></div><div class="comparison-controls"><span>ANTES</span><input id="earth-slider" type="range" min="4" max="96" value="${state.earthSplit}"/><span>DESPUÉS</span></div><p class="map-note">Texturas procedurales de ejemplo. No son productos NISAR, MODIS ni VIIRS.</p></section><div class="stack"><section class="card earth-measures"><div class="overline">CAMBIO ESTIMADO · DEMO</div><div class="earth-main-number">${number(m.change,1)} <small>km²</small></div><p>Variación territorial de ejemplo en ${getRegion(state.regionId).name}.</p><div class="soft-divider"></div><div class="change-detail"><span>Área estudiada</span><strong>120 km²*</strong></div><div class="change-detail"><span>Índice de variación</span><strong>${number(m.change/1.2,1)}%*</strong></div><div class="change-detail"><span>Escenas validadas</span><strong>0 reales</strong></div><div class="change-detail"><span>Modelo</span><strong>EarthVision AI</strong></div><div class="soft-divider"></div><p class="text-small muted">* Valores completamente ficticios.</p></section><section class="card compact-tip">${icon('satellite',19)}<div><strong>Próxima conexión</strong><p>Escenas SAR georreferenciadas y pares temporales de NASA NISAR.</p></div></section></div></div><div class="two-columns bottom-gap"><section class="card info-card"><div class="overline">CAPACIDAD TÉCNICA</div><h2>Detección de cambios</h2><p>El futuro pipeline descargará escenas compatibles, realizará correcciones geoespaciales, calculará diferencias y contrastará resultados con imágenes o máscaras de referencia.</p></section><section class="card info-card"><div class="overline">METODOLOGÍA</div><h2>Interpretación responsable</h2><p>Un cambio en la señal radar no equivale por sí solo a deforestación o daño. La humedad, geometría de adquisición y otros factores afectan la respuesta SAR.</p></section></div>`;}
function markMd(t){return esc(t).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>');}
function modelsView(){return `${pageHead({action:false})}<div class="model-hero"><div><div class="overline">${icon('brain',15)} MULTI-MODEL ENVIRONMENT</div><h2>Una inteligencia, cuatro especialidades.</h2><p>Arquitectura de análisis multimodelo. Las respuestas y puntuaciones mostradas aquí son de demostración; ningún modelo está entrenado o conectado.</p></div><div class="hero-orb">${icon('brain',58)}</div></div><div class="model-list">${state.models.map(m=>`<section class="card model-card"><div class="model-card-top"><div class="model-icon" style="color:${m.color};background:${m.color}14">${icon(m.icon,25)}</div>${badge('SIN CONECTAR')}</div><h3>${esc(m.name)}</h3><p>${esc(m.description)}</p><div class="model-divider"></div><div class="model-info"><span>Método propuesto</span><strong>${esc(m.method)}</strong></div><div class="model-info"><span>Estado</span><strong>Mock / sin pesos</strong></div><button class="btn btn-secondary full-width" data-inference="${m.id}">${icon('zap',16)} Simular inferencia</button></section>`).join('')}</div>${state.modelResult?`<div class="card inference-result"><div>${icon('check',19)} <strong>Inferencia demostrativa — ${esc(state.modelResult.modelId)}</strong></div><p>Resultado: <b>${state.modelResult.score}/100</b> · ${esc(state.modelResult.explanation)}</p><button class="text-link" data-action="clear-inference">Cerrar</button></div>`:''}<div class="ai-workspace"><section class="card chat-panel"><div class="card-header"><div><div class="overline">${icon('bot',15)} TERRA COPILOT</div><h2>Asistente ambiental</h2></div>${badge('RESPUESTAS SIMULADAS','purple')}</div><div class="chat-messages" id="chat-messages">${state.chat.map(msg=>`<div class="chat-msg ${msg.role}"><span class="chat-avatar">${msg.role==='assistant'?icon('brain',17):'T'}</span><div class="chat-bubble">${markMd(msg.text)}${msg.sources?`<div class="chat-sources">${msg.sources.map(s=>`<span>${icon('book',12)} ${esc(s)}</span>`).join('')}</div>`:''}</div></div>`).join('')}${state.assistantBusy?`<div class="chat-typing">${icon('activity',16)} Analizando escenario de demostración…</div>`:''}</div><form id="chat-form" class="chat-form"><input id="chat-input" autocomplete="off" maxlength="300" placeholder="Pregunta sobre lluvias, incendios o agricultura…" required/><button type="submit" aria-label="Enviar mensaje">${icon('send',19)}</button></form><div class="chat-hints">${['¿Qué indica el riesgo de incendios?','¿Cómo están las lluvias?','¿Qué significa el análisis SAR?'].map(a=>`<button data-prompt="${esc(a)}">${esc(a)}</button>`).join('')}</div></section><section class="card fusion-panel"><div class="card-header"><div><div class="overline">TERRA FUSION ENGINE</div><h2>Fusión de conocimientos</h2></div>${icon('layers',20)}</div><div class="fusion-visual"><span class="fusion-core">${icon('brain',35)}<small>FUSION</small></span>${state.models.map((m,i)=>`<span class="fusion-node n${i+1}" style="--node:${m.color}">${icon(m.icon,18)}</span>`).join('')}</div><h3>Conexiones preparadas</h3><p>Una capa de orquestación combinará resultados de los modelos especializados, fuentes georreferenciadas y sus niveles de confianza.</p><div class="fusion-stat"><span>${icon('plug',16)} Modelos reales conectados</span><strong>0 / 4</strong></div><div class="fusion-stat"><span>${icon('database',16)} Datasets reales vinculados</span><strong>0 / 4</strong></div><button data-nav="integrations" class="btn btn-secondary full-width">Ver contrato de integraciones ${icon('arrow',15)}</button></section></div>`;}
function alertsView(){const filtered=state.alerts.filter(a=>state.alertFilter==='all'||a.level===state.alertFilter);return `${pageHead({action:false})}<div class="alert-status-strip"><div class="alert-status-ico">${icon('bell',22)}</div><div><strong>Monitor de eventos de demostración</strong><p>Las notificaciones no proceden de organismos oficiales. Solo prueban flujos y visualizaciones.</p></div>${badge(`${state.alerts.length} escenarios`)}</div><div class="scope-row"><div class="filter-bar">${[['all','Todos'],['critical','Críticos'],['warning','En observación'],['info','Informativos']].map(([k,label])=>`<button data-alert-filter="${k}" class="filter-chip ${state.alertFilter===k?'active':''}">${label}</button>`).join('')}</div><span class="muted text-small">${filtered.length} resultados</span></div><div class="alerts-list">${filtered.map(a=>`<button class="card alert-item" data-alert="${a.id}"><div class="alert-icon ${a.level}">${icon(a.icon,23)}</div><div class="alert-item-main"><div class="alert-item-top">${badge(a.level==='critical'?'Prioridad alta':a.level==='warning'?'Observación':'Informativo',a.level==='critical'?'danger':a.level==='warning'?'warning':'neutral')}<span>${esc(a.type)}</span><span>Hace ${a.hours} h</span></div><h3>${esc(a.title)}</h3><p>${esc(a.text)}</p><small>${icon('pin',13)} ${esc(a.area)}</small></div>${icon('chevron',20,'muted')}</button>`).join('')}</div>`;}
function reportsView(){const r=getRegion(state.regionId);return `${pageHead({action:false})}<div class="reports-hero"><div><div class="overline">EXPORTACIÓN REPRODUCIBLE</div><h2>Información lista para compartir</h2><p>Genera informes y datos de demostración. Todos los documentos incluyen el aviso de que los valores son ficticios.</p></div>${icon('file',66)}</div><div class="report-grid">${[
 ['Informe territorial','Resumen, métricas, narrativas y metodología.','file','export-html','Generar HTML'],['Series temporales','Intervalos de temperatura, lluvia y actividad térmica.','chart','export-csv','Descargar CSV'],['Dataset sintético','Registros de ejemplo para integrar y probar APIs.','database','export-json','Descargar JSON']
 ].map(([title,desc,ico,act,btn])=>`<section class="card report-card"><div class="report-icon">${icon(ico,25)}</div><h3>${title}</h3><p>${desc}</p><div class="report-meta">${icon('pin',14)} ${esc(r.name)} <span>·</span> ${state.period}</div><button class="btn btn-secondary full-width" data-action="${act}">${icon('download',16)} ${btn}</button></section>`).join('')}</div><div class="card checklist-panel"><div class="card-header"><div><div class="overline">TRAZABILIDAD</div><h2>Contenido de las exportaciones</h2></div>${badge('MODO DEMO')}</div><div class="checklist-grid">${[['Datos con procedencia identificada','Tipo de fuente y periodo de referencia'],['Esquema JSON compatible','Contratos para reemplazar fixtures'],['Avisos de incertidumbre','Separación explícita entre ficción y ciencia'],['Formato portable','CSV, JSON e informe HTML imprimible']].map(x=>`<div>${icon('check',17)}<span><strong>${x[0]}</strong><small>${x[1]}</small></span></div>`).join('')}</div></div>`;}
function integrationsView(){return `${pageHead({showRegion:false,action:false})}<div class="connections-summary"><div><div class="overline">DATA INFRASTRUCTURE</div><h2>Conectores listos para conectar.</h2><p>El sistema utiliza proveedores intercambiables. Sustituye el adaptador MockProvider por APIProvider sin rediseñar los módulos visuales.</p></div><div class="connection-numbers"><strong>8</strong><span>interfaces previstas</span></div></div><div class="integrations-grid">${state.integrations.map(c=>`<section class="card connector-card"><div class="connector-top"><div class="connector-logo">${icon(c.id==='model'?'brain':c.id==='supabase'?'database':c.id==='r2'?'layers':c.id==='nisar'?'satellite':c.id==='firms'?'flame':'cloud-sun',23)}</div>${badge('NO CONFIGURADO')}</div><h3>${esc(c.name)}</h3><p>${esc(c.role)}</p><div class="connector-row"><span>Categoría</span><strong>${esc(c.category)}</strong></div><div class="connector-row"><span>Frecuencia</span><strong>${esc(c.frequency)}</strong></div><div class="connector-actions"><button class="btn btn-secondary" data-connector="${c.id}">${icon('plug',16)} Ver conexión</button><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer" class="connector-link" title="Documentación oficial">${icon('external',17)}</a></div></section>`).join('')}</div><div class="card integration-help"><div>${icon('info',21)}</div><p><strong>Arquitectura desacoplada.</strong> Los puntos de conexión están definidos en <code>src/services/api-provider.js</code> y documentados en <code>CONEXIONES.md</code>. El servidor local ofrece endpoints ficticios para probar el contrato HTTP.</p><button class="btn btn-secondary" data-action="copy-config">${icon('copy',16)} Copiar configuración</button></div>`;}
function settingsView(){return `${pageHead({showRegion:false,action:false})}<div class="settings-layout"><section class="card settings-card"><div class="card-header"><div><div class="overline">ENTORNO DE EJECUCIÓN</div><h2>Estado de la plataforma</h2></div>${badge('ACTIVO','good')}</div><div class="settings-row"><div>${icon('monitor',19)} <span>Tipo de ejecución</span></div><strong>Demo local ejecutable</strong></div><div class="settings-row"><div>${icon('database',19)} <span>Proveedor de datos</span></div><strong>${providerMode==='mock'?'MockProvider (en memoria)':'APIProvider (HTTP)'}</strong></div><div class="settings-row"><div>${icon('shield',19)} <span>Datos reales</span></div><strong class="warn-text">No conectados</strong></div><div class="settings-row"><div>${icon('brain',19)} <span>Modelos entrenados</span></div><strong>0 / 4</strong></div><div class="settings-row"><div>${icon('cloud',19)} <span>Backend de producción</span></div><strong>Pendiente</strong></div><button class="btn btn-secondary" data-action="refresh">${icon('refresh',16)} Verificar simulador</button></section><section class="card settings-card"><div class="card-header"><div><div class="overline">CONFIGURACIÓN DE DESARROLLO</div><h2>Enchufes disponibles</h2></div>${icon('plug',21)}</div><p>La estructura contiene separaciones explícitas para cambiar fuentes, base de datos e inferencia ML.</p><div class="code-snippet"><div>// config.js — configuración de ejemplo</div><div><span>provider</span>: 'mock' // → 'api'</div><div><span>apiBaseUrl</span>: '/api/v1'</div><div><span>simulationLabel</span>: true</div></div><p class="muted text-small">No almacenes secretos de Supabase, NASA ni R2 en el navegador. Deben configurarse en el servidor.</p><button class="btn btn-secondary" data-action="copy-config">${icon('copy',16)} Copiar ejemplo de configuración</button></section></div><div class="card settings-card bottom-gap"><div class="overline">INSTRUCCIONES DE ARRANQUE</div><h2>Preparado para Windows, macOS y Linux</h2><div class="launch-grid"><div><strong>Windows</strong><code>INICIAR_DEMO.bat</code></div><div><strong>Mac / Linux</strong><code>./INICIAR_DEMO.sh</code></div><div><strong>Node.js</strong><code>npm start</code></div><div><strong>Dirección</strong><code>http://localhost:4173</code></div></div></div>`;}
function modal(){if(!state.modal)return '';return `<div class="modal-overlay" data-action="close-modal"><div class="modal-card" role="dialog" aria-modal="true" aria-label="${esc(state.modal.title)}"><div class="modal-header"><div><div class="overline">TERRA WORKSPACE</div><h2>${esc(state.modal.title)}</h2></div><button data-action="close-modal" class="icon-button">${icon('close',20)}</button></div><div class="modal-content">${state.modal.html}</div><div class="modal-footer"><button class="btn btn-secondary" data-action="close-modal">Cerrar</button></div></div></div>`;}
function searchModal(){const list=state.regions.filter(r=>`${r.name} ${r.country}`.toLowerCase().includes(state.search.toLowerCase()));return `<div class="modal-overlay" data-action="close-modal"><div class="search-dialog" role="dialog" aria-modal="true"><div class="search-input-row">${icon('search',21)}<input id="global-search" autofocus placeholder="Busca Huánuco, Perú, incendios, clima..." value="${esc(state.search)}"/><span class="keycap">ESC</span></div><div class="search-results"><div class="search-category">REGIONES</div>${list.slice(0,7).map(r=>`<button data-region="${r.id}">${icon('pin',17)} <span>${esc(r.name)}, ${esc(r.country)}</span>${icon('arrow',16)}</button>`).join('')||'<p class="empty-search">No hay regiones con ese nombre.</p>'}<div class="search-category">MÓDULOS</div>${Object.entries(PAGES).filter(([id,x])=>`${x[0]} ${x[1]}`.toLowerCase().includes(state.search.toLowerCase())).slice(0,5).map(([id,x])=>`<button data-nav="${id}">${icon(x[2],17)}<span>${esc(x[0])}</span>${icon('arrow',16)}</button>`).join('')}</div></div></div>`;}
function footer(){return `<footer class="app-footer"><span>© 2026 TERRA AI · Concepto de demostración de SANTRIX</span><span>Geografía: Natural Earth (dominio público) · <b>DATOS FICTICIOS</b> · Preparado para integraciones</span></footer>`;}
function render(){destroyMap();if(state.loading){app.innerHTML='<div class="loading-screen"><span class="spinner"></span><h1>TERRA <em>AI</em></h1><p>Preparando los módulos científicos…</p></div>';return;}
 const page={overview,map:mapView,climate:climateView,fire:fireView,agro:agroView,earth:earthView,models:modelsView,alerts:alertsView,reports:reportsView,integrations:integrationsView,settings:settingsView}[state.page]||overview;
 const content=(state.dashboard&&state.series)?page():`<div class="card unavailable"><h2>Origen de datos no disponible</h2><p>La interfaz no recibió los contratos de datos necesarios. Verifica APIProvider y la ruta HTTP, o usa el modo mock en config.js.</p><button class="btn btn-secondary" data-action="refresh">${icon('refresh',16)} Volver a intentar</button></div>`;
 app.innerHTML=`<div class="shell">${aside()}<div class="work-area">${topbar()}<main class="main-content">${demoStrip()}${state.error?`<div class="error-banner">${icon('alert',17)} ${esc(state.error)} · Verifica el adaptador y reinicia.</div>`:''}${content}${footer()}</main></div>${state.sidebarMobile?'<div class="sidebar-backdrop" data-action="sidebar"></div>':''}${state.modal?(state.modal.type==='search'?searchModal():modal()):''}${state.toast?`<div class="toast">${icon('check',16)} ${esc(state.toast)}</div>`:''}</div>`;
 if(document.getElementById('geo-viewer')) destroyMap=mountMap(document.getElementById('geo-viewer'),{hotspots:state.hotspots,regionId:state.regionId,layers:state.layers,onSelect:id=>setRegion(id),globalView:state.page==='map'});
 document.getElementById('chat-messages')?.scrollTo(0,200000);
 if(state.modal?.type==='search'){const inp=document.getElementById('global-search');inp?.focus();inp?.setSelectionRange(inp.value.length,inp.value.length);}
}
async function loadData(){try{const [dashboard,series,hotspots]=await Promise.all([provider.getDashboard(state.regionId,state.period),provider.getSeries(state.regionId,state.period),provider.getHotspots(state.page==='map'?'global':state.regionId,state.period)]);state.dashboard=dashboard;state.series=series;state.hotspots=hotspots;state.lastUpdate=Date.now();state.error=null;}catch(e){state.error=e.message||'Error al cargar el origen de datos.';}finally{state.loading=false;render();}}
async function setRegion(id){if(!state.regions.find(r=>r.id===id))return;state.regionId=id;state.modal=null;state.sidebarMobile=false;await loadData();}
async function setPeriod(per){state.period=per;await loadData();}
function setPage(page){if(!PAGES[page])return;state.page=page;state.modal=null;state.sidebarMobile=false;window.scrollTo({top:0,behavior:'instant'});if(page==='map'||page==='fire')loadData();else render();}
function alertDetails(id){const a=state.alerts.find(x=>x.id===id);if(!a)return;state.modal={title:a.title,html:`<div class="alert-modal-meta">${badge(a.level==='critical'?'Prioridad alta':a.level==='warning'?'En observación':'Informativo',a.level==='critical'?'danger':a.level==='warning'?'warning':'neutral')}<span>${esc(a.area)} · hace ${a.hours} h</span></div><p>${esc(a.text)}</p><div class="notice-strong">${icon('info',18)} Esta es una notificación totalmente ficticia y no constituye una advertencia oficial ni un aviso de emergencia.</div><button class="btn btn-primary" data-region="${a.regionId}">Analizar territorio ${icon('arrow',16)}</button>`};render();}
function connectorDetails(id){const c=state.integrations.find(x=>x.id===id);if(!c)return;state.modal={title:`Conectar ${c.name}`,html:`<p>${esc(c.role)}. El conector está diseñado como punto de extensión. Para habilitarlo, implementa el servicio backend y la autenticación apropiada.</p><div class="integration-detail"><span>Servicio propuesto</span><code>${esc(c.route)}</code></div><div class="integration-detail"><span>Actualización orientativa</span><strong>${esc(c.frequency)}</strong></div><div class="integration-detail"><span>Estado actual</span>${badge('SIN CREDENCIALES · NO CONECTADO')}</div><div class="notice-strong">${icon('shield',17)} Mantener las claves y secretos únicamente en variables de entorno del backend, nunca en config.js.</div><a class="btn btn-secondary" target="_blank" rel="noopener noreferrer" href="${esc(c.url)}">Documentación del proveedor ${icon('external',16)}</a>`};render();}
function exportFile(filename,data,type='text/plain;charset=utf-8'){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast(`Archivo ${filename} generado con datos ficticios.`);}
function exportCSV(){const s=state.series;let lines=['intervalo,temperatura_c,precipitacion_mm,focos_termicos,vegetacion_pct,riesgo_indice'];s.labels.forEach((l,i)=>lines.push([l,s.temp[i],s.rain[i],s.fire[i],s.vegetation[i],s.risk[i]].join(',')));exportFile(`terra-demo-${state.regionId}-${state.period}.csv`,'# DATOS TOTALMENTE SIMULADOS - NO SON OBSERVACIONES SATELITALES\n'+lines.join('\n'),'text/csv;charset=utf-8');}
function exportJSON(){exportFile(`terra-demo-${state.regionId}.json`,JSON.stringify({warning:'DATOS FICTICIOS. No usar para tomar decisiones reales.',generatedAt:new Date().toISOString(),region:state.dashboard.region,metrics:state.dashboard.metrics,series:state.series,hotspots:state.hotspots,alerts:state.alerts},null,2),'application/json;charset=utf-8');}
function exportHTML(){const m=state.dashboard.metrics,r=getRegion(state.regionId),ts=new Date().toLocaleString('es-PE');const d=`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>TERRA AI | Informe de ${esc(r.name)}</title><style>body{font-family:system-ui,sans-serif;color:#1e2b34;max-width:800px;margin:48px auto;line-height:1.6;padding:0 22px}.label{color:#15836d;font-weight:700;letter-spacing:2px}.warn{padding:16px;border:1px solid #f7a36d;background:#fff8ed;border-radius:10px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.box{border:1px solid #d6e1e0;padding:16px;border-radius:10px}.box strong{font-size:27px;display:block}h1{font-size:36px}hr{border:0;border-top:1px solid #dde7e7;margin:30px 0}small{color:#6a7881}@media print{button{display:none}}</style></head><body><div class="label">TERRA AI · EARTH INTELLIGENCE</div><h1>Informe territorial: ${esc(r.name)}</h1><p>${esc(r.country)} · ${ts}</p><p class="warn"><b>INFORME DE DEMOSTRACIÓN.</b> Todos los datos, métricas e interpretaciones contenidos en este documento son ficticios, no observacionales y no aptos para decisiones operativas.</p><h2>Indicadores ilustrativos</h2><div class="grid"><div class="box">Temperatura<strong>${number(m.temp,1)} °C</strong></div><div class="box">Focos térmicos<strong>${m.hotspots}</strong></div><div class="box">Precipitación<strong>${m.precip} mm</strong></div><div class="box">Humedad del suelo<strong>${m.soil}%</strong></div></div><hr/><h2>Interpretación</h2><p>${esc(state.dashboard.narrative)}</p><h2>Próximas conexiones</h2><p>NASA FIRMS · NASA POWER · NASA GPM IMERG · NASA NISAR · Model serving · PostgreSQL / PostGIS.</p><h2>Metodología y limitaciones</h2><p>El presente documento es generado con un simulador determinista. Para un informe científico se requerirán datasets observacionales, control de calidad, fechas y procedencia de datos, validación de los modelos y cuantificación de incertidumbre.</p><small>Desarrollado como demostración técnica de una arquitectura extensible. © 2026 TERRA AI / SANTRIX.</small><p><button onclick="window.print()">Imprimir / Guardar como PDF</button></p></body></html>`;exportFile(`informe-terra-${state.regionId}.html`,d,'text/html;charset=utf-8');}
async function sendMessage(message){if(!message.trim()||state.assistantBusy)return;state.chat.push({role:'user',text:message.trim()});state.assistantBusy=true;render();try{const answer=await provider.askAssistant(message.trim(),state.regionId);state.chat.push({role:'assistant',...answer});}catch(e){state.chat.push({role:'assistant',text:`No se pudo consultar el adaptador: ${e.message}`});}finally{state.assistantBusy=false;render();}}
async function runInference(modelId){state.modelBusy=true;state.modelResult=null;toast('Ejecutando simulación de inferencia…');try{state.modelResult=await provider.runInference(modelId,state.regionId);}catch(e){toast(`No se pudo realizar inferencia: ${e.message}`);}finally{state.modelBusy=false;render();}}
function handleAction(action){if(action==='search'){state.modal={type:'search'};state.search='';render();}else if(action==='sidebar'){state.sidebarMobile=!state.sidebarMobile;render();}else if(action==='refresh'){loadData().then(()=>toast('Los datos sintéticos se han regenerado.'));}else if(action==='close-modal'){state.modal=null;render();}else if(action==='export-csv')exportCSV();else if(action==='export-json')exportJSON();else if(action==='export-html')exportHTML();else if(action==='reset-agro'){state.deltaRain=0;state.deltaTemp=0;render();}else if(action==='clear-inference'){state.modelResult=null;render();}else if(action==='copy-config'){navigator.clipboard?.writeText("window.TERRA_CONFIG = { provider: 'api', apiBaseUrl: '/api/v1', simulationLabel: false };").then(()=>toast('Configuración copiada.')).catch(()=>toast('Copia el ejemplo del archivo config.js.'));}}
app.addEventListener('click',e=>{
 const btn=e.target.closest('[data-nav],[data-region],[data-period],[data-layer],[data-hotspot],[data-hotspot-row],[data-alert],[data-action],[data-connector],[data-inference],[data-prompt],[data-alert-filter]');if(!btn)return;
 if(btn.dataset.action==='close-modal'&&btn.classList?.contains('modal-overlay')&&e.target.closest('.modal-card,.search-dialog'))return;
 if(btn.dataset.nav)setPage(btn.dataset.nav);
 else if(btn.dataset.region)setRegion(btn.dataset.region);
 else if(btn.dataset.period)setPeriod(btn.dataset.period);
 else if(btn.dataset.layer){state.layers=state.layers.includes(btn.dataset.layer)?state.layers.filter(l=>l!==btn.dataset.layer):[...state.layers,btn.dataset.layer];render();}
 else if(btn.dataset.hotspot){state.hotspotFilter=btn.dataset.hotspot;render();}
 else if(btn.dataset.hotspotRow){const h=state.hotspots.find(x=>x.id===btn.dataset.hotspotRow);if(h){state.modal={title:`Registro ${h.id}`,html:`<p>Detección térmica completamente ficticia. Sirve para demostrar la interfaz de inspección y los contratos de datos.</p><div class="integration-detail"><span>Coordenadas</span><strong>${h.lat}, ${h.lon}</strong></div><div class="integration-detail"><span>Fuente asignada</span><strong>${h.source} (SIMULADA)</strong></div><div class="integration-detail"><span>FRP ficticia</span><strong>${h.frp} MW</strong></div><div class="integration-detail"><span>Confianza ficticia</span><strong>${h.confidence}%</strong></div>`};render();}}
 else if(btn.dataset.alert)alertDetails(btn.dataset.alert);
 else if(btn.dataset.connector)connectorDetails(btn.dataset.connector);
 else if(btn.dataset.inference)runInference(btn.dataset.inference);
 else if(btn.dataset.prompt)sendMessage(btn.dataset.prompt);
 else if(btn.dataset.alertFilter){state.alertFilter=btn.dataset.alertFilter;render();}
 else if(btn.dataset.action)handleAction(btn.dataset.action);
});
app.addEventListener('change',e=>{
 if(e.target.id==='region-select')setRegion(e.target.value);
 else if(e.target.id==='crop'){state.crop=e.target.value;render();}
 else if(e.target.id==='delta-rain'){state.deltaRain=Number(e.target.value);render();}
 else if(e.target.id==='delta-temp'){state.deltaTemp=Number(e.target.value);render();}
 else if(e.target.id==='earth-slider'){state.earthSplit=Number(e.target.value);render();}
});
app.addEventListener('input',e=>{
 if(e.target.id==='global-search'){const pos=e.target.selectionStart;state.search=e.target.value;render();const input=document.getElementById('global-search');input?.setSelectionRange(pos,pos);}
 if(e.target.id==='earth-slider'){state.earthSplit=Number(e.target.value);document.getElementById('earth-after')?.style.setProperty('clip-path',`inset(0 ${100-state.earthSplit}% 0 0)`);document.getElementById('split-divider')?.style.setProperty('left',`${state.earthSplit}%`);}
 if(e.target.id==='delta-rain'||e.target.id==='delta-temp'){state[e.target.id==='delta-rain'?'deltaRain':'deltaTemp']=Number(e.target.value);}
});
app.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();const v=e.target.querySelector('#chat-input')?.value||'';sendMessage(v);}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();handleAction('search');}if(e.key==='Escape'&&state.modal){state.modal=null;render();}});
async function start(){try{const [regions,alerts,integrations,models]=await Promise.all([provider.getRegions(),provider.getAlerts(),provider.getIntegrations(),provider.getModels()]);state.regions=regions;state.alerts=alerts;state.integrations=integrations;state.models=models;}catch(e){state.error=e.message||'No se han podido cargar los datos.';state.loading=false;render();return;}await loadData();}
start();
const refreshInterval=Math.max(0,Number(window.TERRA_CONFIG?.refreshSeconds||0));
if(refreshInterval>0)setInterval(()=>{if(!document.hidden&&!state.loading&&!state.assistantBusy&&!state.modal&&['overview','map','fire','climate'].includes(state.page))loadData();},refreshInterval*1000);
